72	<body>
73	<canvas id="c"></canvas>
74	<div class="hud-layer">
75	  <div class="header">
76	    <div class="sub-title">Prismatic Refraction Matrix</div>
77	    <div class="main-title">Chrono Prism · Stress Shatter & Crystal Flow</div>
78	    <div class="pool-vault" id="poolVault">
79	      <div class="vault-icon">💎</div>
80	      <div class="vault-meta">
81	        <span class="vault-lbl">Accumulated Permanent Pool</span>
82	        <span class="vault-val" id="poolVal">0s</span>
83	      </div>
84	    </div>
85	  </div>
86	
87	  <div class="burst-badge" id="burstBadge">
88	    <span class="burst-lbl" id="burstLabel">PRISM CHARGE</span>
89	    <span class="burst-val" id="burstVal">0s</span>
90	  </div>
91	
92	  <div class="controls">
93	    <button class="btn" onclick="depositSession(1800)">Deposit 30m</button>
94	    <button class="btn" onclick="depositSession(7200)">Deposit 2h</button>
95	    <button class="btn" onclick="depositSession(21600)">Deposit 6h</button>
96	    <button class="btn" onclick="resetAll()">Reset</button>
97	  </div>
98	</div>
99	
100	<script>
101	const canvas = document.getElementById('c'), ctx = canvas.getContext('2d');
102	const poolVaultEl = document.getElementById('poolVault'), poolValEl = document.getElementById('poolVal');
103	const burstBadgeEl = document.getElementById('burstBadge'), burstLabelEl = document.getElementById('burstLabel');
104	const burstValEl = document.getElementById('burstVal');
105	
106	let W, H, cx, cy, targetX = 0, targetY = 0, permanentSec = 0, displayPermanentSec = 0;
107	let isSpooling = false, spoolSec = 0, targetSpoolSec = 0, spoolProgress = 0;
108	let prismPulse = 0, screenShake = 0, shards = [], shockwaves = [], cracks = [], audioCtx = null, lingerTimeout = null;
109	
110	function resize() {
111	  W = canvas.width = window.innerWidth; H = canvas.height = window.innerHeight; cx = W / 2; cy = H / 2 - 20;
112	  const r = poolVaultEl.getBoundingClientRect(); targetX = r.left + r.width / 2; targetY = r.top + r.height / 2;
113	}
114	window.addEventListener('resize', resize);
115	resize();
116	
117	function formatDuration(sec) {
118	  if (!sec || isNaN(sec) || sec < 0) return '0s';
119	  let s = Math.floor(sec);
120	  const Y = Math.floor(s / 31536000); s %= 31536000;
121	  const M = Math.floor(s / 2592000); s %= 2592000;
122	  const D = Math.floor(s / 86400); s %= 86400;
123	  const h = Math.floor(s / 3600); s %= 3600;
124	  const m = Math.floor(s / 60); const rem = s % 60;
125	  const p = [];
126	  if (Y > 0) p.push(`${Y}Y`); if (M > 0) p.push(`${M}M`); if (D > 0) p.push(`${D}D`);
127	  if (h > 0) p.push(`${h}h`); if (m > 0) p.push(`${m}m`); if (rem > 0 || p.length === 0) p.push(`${rem}s`);
128	  return p.join('');
129	}
130	
131	function playGlassSound(type, freq = 600) {
132	  try {
133	    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
134	    if (audioCtx.state === 'suspended') audioCtx.resume();
135	    const t = audioCtx.currentTime, osc = audioCtx.createOscillator(), gain = audioCtx.createGain();
136	    if (type === 'tick') {
137	      osc.type = 'sine'; osc.frequency.setValueAtTime(freq, t); gain.gain.setValueAtTime(0.04, t);
138	      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.04); osc.start(t); osc.stop(t + 0.04);
139	    } else if (type === 'shatter') {
140	      osc.type = 'sawtooth'; osc.frequency.setValueAtTime(1200, t); osc.frequency.exponentialRampToValueAtTime(80, t + 0.45);
141	      gain.gain.setValueAtTime(0.4, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.45); osc.start(t); osc.stop(t + 0.45);
142	    } else {
143	      osc.type = 'sine'; osc.frequency.setValueAtTime(freq, t); gain.gain.setValueAtTime(0.05, t);
144	      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.08); osc.start(t); osc.stop(t + 0.08);
145	    }
146	    osc.connect(gain); gain.connect(audioCtx.destination);
147	  } catch(e) {}
148	}
149	
150	function depositSession(seconds) {
151	  isSpooling = true; targetSpoolSec = seconds; spoolSec = 0; spoolProgress = 0; cracks = [];
152	  clearTimeout(lingerTimeout);
153	  burstBadgeEl.className = 'burst-badge spooling'; burstValEl.className = 'burst-val';
154	  burstLabelEl.textContent = 'PRISM CHARGE'; burstValEl.textContent = '0s';
155	}
156	
157	function triggerShatter() {
158	  isSpooling = false; playGlassSound('shatter');
159	  screenShake = Math.min(32, 10 + (targetSpoolSec / 3600) * 4);
160	  shockwaves.push({ r: 25, maxR: Math.min(W, H) * 0.65, alpha: 1.0 });
161	
162	  burstLabelEl.textContent = 'CRYSTAL YIELD';
163	  burstValEl.textContent = formatDuration(targetSpoolSec);
164	  burstValEl.className = 'burst-val lingering';
165	  burstBadgeEl.className = 'burst-badge slow-fade';
166	
167	  const pCount = Math.min(220, Math.max(45, Math.floor(targetSpoolSec / 80)));
168	  const secPerP = targetSpoolSec / pCount;
169	  for (let i = 0; i < pCount; i++) {
170	    const a = Math.random() * Math.PI * 2, sp = 5 + Math.random() * 16;
171	    shards.push({
172	      x: cx, y: cy, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 2,
173	      secVal: secPerP, age: 0, magnetWait: 14 + Math.random() * 16,
174	      rot: Math.random() * Math.PI * 2, vRot: (Math.random() - 0.5) * 0.4,
175	      size: 4 + Math.random() * 4, color: Math.random() > 0.4 ? '#e879f9' : '#38bdf8'
176	    });
177	  }
178	
179	  clearTimeout(lingerTimeout);
180	  lingerTimeout = setTimeout(() => { burstBadgeEl.className = 'burst-badge'; }, 1000);
181	}
182	
183	function resetAll() {
184	  clearTimeout(lingerTimeout); isSpooling = false; permanentSec = 0; displayPermanentSec = 0;
185	  shards = []; shockwaves = []; cracks = []; screenShake = 0; poolValEl.textContent = '0s';
186	  burstBadgeEl.className = 'burst-badge'; burstValEl.className = 'burst-val';
187	}
188	
189	function drawPrismShape(size, rot) {
190	  ctx.save(); ctx.translate(cx, cy); ctx.rotate(rot); ctx.beginPath();
191	  for (let i = 0; i < 6; i++) {
192	    const a = (i / 6) * Math.PI * 2;
193	    const px = Math.cos(a) * size, py = Math.sin(a) * (size * 0.85);
194	    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
195	  }
196	  ctx.closePath();
197	  ctx.strokeStyle = isSpooling ? '#f5d0fe' : '#c084fc'; ctx.lineWidth = 2.5;
198	  ctx.shadowColor = '#d946ef'; ctx.shadowBlur = isSpooling ? 28 : 16; ctx.stroke();
199	  ctx.restore();
200	}
201	
202	function draw() {
203	  ctx.save();
204	  if (screenShake > 0) {
205	    ctx.translate((Math.random() - 0.5) * screenShake, (Math.random() - 0.5) * screenShake);
206	    screenShake *= 0.88; if (screenShake < 0.2) screenShake = 0;
207	  }
208	  ctx.fillStyle = 'rgba(4, 2, 8, 0.28)'; ctx.fillRect(-20, -20, W + 40, H + 40);
209	  const t = Date.now() * 0.002;
210	
211	  if (isSpooling) {
212	    spoolProgress += 0.045;
213	    spoolSec = Math.round(targetSpoolSec * Math.min(1.0, Math.pow(spoolProgress, 1.3)));
214	    burstValEl.textContent = formatDuration(spoolSec);
215	    screenShake = 1.0 + spoolProgress * 8;
216	    playGlassSound('tick', 500 + spoolProgress * 700);
217	
218	    drawPrismShape(42 + spoolProgress * 38 + Math.sin(t * 14) * 3, t * 1.5);
219	    if (spoolProgress > 0.6 && Math.random() < 0.35) {
220	      const ca = Math.random() * Math.PI * 2, cd = 10 + Math.random() * 45;
221	      cracks.push({ x1: cx, y1: cy, x2: cx + Math.cos(ca) * cd, y2: cy + Math.sin(ca) * cd });
222	    }
223	    ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5;
224	    for (const c of cracks) {
225	      ctx.beginPath(); ctx.moveTo(c.x1, c.y1); ctx.lineTo(c.x2, c.y2); ctx.stroke();
226	    }
227	    if (spoolProgress >= 1.0) triggerShatter();
228	  } else {
229	    drawPrismShape(36 + Math.sin(t * 3) * 2, t * 0.8);
230	  }
231	
232	  // Shockwaves
233	  for (let i = shockwaves.length - 1; i >= 0; i--) {
234	    const sw = shockwaves[i]; sw.r += 14; sw.alpha -= 0.035;
235	    if (sw.alpha <= 0) { shockwaves.splice(i, 1); continue; }
236	    ctx.beginPath(); ctx.arc(cx, cy, sw.r, 0, Math.PI * 2);
237	    ctx.strokeStyle = `rgba(240, 171, 252, ${sw.alpha})`; ctx.lineWidth = 4;
238	    ctx.shadowColor = '#c084fc'; ctx.shadowBlur = 18; ctx.stroke();
239	  }
240	
241	  // Shard Swarm Ingestion
242	  for (let i = shards.length - 1; i >= 0; i--) {
243	    const p = shards[i]; p.age++; p.rot += p.vRot;
244	    if (p.age < p.magnetWait) {
245	      p.x += p.vx; p.y += p.vy; p.vx *= 0.94; p.vy *= 0.94;
246	    } else {
247	      const dx = targetX - p.x, dy = targetY - p.y, dist = Math.hypot(dx, dy);
248	      if (dist < 26) {
249	        permanentSec += p.secVal; poolVaultEl.classList.add('absorb');
250	        setTimeout(() => poolVaultEl.classList.remove('absorb'), 70);
251	        playGlassSound('chime', 880 + (p.age % 10) * 80);
252	        shards.splice(i, 1); continue;
253	      }
254	      const pull = Math.min(26, 2.0 + (p.age - p.magnetWait) * 0.95);
255	      p.vx = (dx / dist) * pull; p.vy = (dy / dist) * pull; p.x += p.vx; p.y += p.vy;
256	    }
257	    ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(p.rot);
258	    ctx.beginPath(); ctx.moveTo(-p.size, -p.size); ctx.lineTo(p.size, 0); ctx.lineTo(0, p.size); ctx.closePath();
259	    ctx.fillStyle = p.color; ctx.shadowColor = p.color; ctx.shadowBlur = 10; ctx.fill();
260	    ctx.restore();
261	  }
262	
263	  if (displayPermanentSec < permanentSec) {
264	    displayPermanentSec += Math.ceil((permanentSec - displayPermanentSec) * 0.2);
265	    poolValEl.textContent = formatDuration(displayPermanentSec);
266	  }
267	  ctx.restore();
268	  requestAnimationFrame(draw);
269	}
270	requestAnimationFrame(draw);
271	</script>
272	</body>
273	</html>

