240	    ctx.beginPath(); ctx.arc(cx, cy, idleR, 0, Math.PI * 2);
241	    ctx.fillStyle = 'rgba(249, 115, 22, 0.35)'; ctx.shadowColor = '#f97316'; ctx.shadowBlur = 16; ctx.fill();
242	  }
243	
244	  // Draw Lightning Arcs
245	  ctx.strokeStyle = '#fde047'; ctx.lineWidth = 1.8;
246	  for (let i = arcs.length - 1; i >= 0; i--) {
247	    const a = arcs[i]; ctx.beginPath(); ctx.moveTo(a.x1, a.y1);
248	    ctx.lineTo((a.x1 + a.x2) / 2 + (Math.random() - 0.5) * 16, (a.y1 + a.y2) / 2 + (Math.random() - 0.5) * 16);
249	    ctx.lineTo(a.x2, a.y2); ctx.stroke();
250	    if (--a.life <= 0) arcs.splice(i, 1);
251	  }
252	
253	  // Phase 2: Particles Stream to Permanent Pool
254	  for (let i = particles.length - 1; i >= 0; i--) {
255	    const p = particles[i]; p.age++;
256	    if (p.age < p.magnetWait) {
257	      p.x += p.vx; p.y += p.vy; p.vx *= 0.94; p.vy *= 0.94;
258	    } else {
259	      const dx = targetX - p.x, dy = targetY - p.y, dist = Math.hypot(dx, dy);
260	      if (dist < 26) {
261	        permanentSec += p.secVal; poolVaultEl.classList.add('absorb');
262	        setTimeout(() => poolVaultEl.classList.remove('absorb'), 70);
263	        playSound('absorb', 880 + (p.age % 10) * 75);
264	        particles.splice(i, 1); continue;
265	      }
266	      const pull = Math.min(26, 2.0 + (p.age - p.magnetWait) * 0.95);
267	      p.vx = (dx / dist) * pull; p.vy = (dy / dist) * pull;
268	      p.x += p.vx; p.y += p.vy;
269	    }
270	    ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
271	    ctx.fillStyle = p.color; ctx.shadowColor = p.color; ctx.shadowBlur = 10; ctx.fill();
272	  }
