275	  for (let i = shockwaves.length - 1; i >= 0; i--) {
276	    const sw = shockwaves[i]; sw.r += 14; sw.alpha -= 0.035;
277	    if (sw.alpha <= 0) { shockwaves.splice(i, 1); continue; }
278	    ctx.beginPath(); ctx.arc(cx, cy, sw.r, 0, Math.PI * 2);
279	    ctx.strokeStyle = `rgba(254, 240, 138, ${sw.alpha})`; ctx.lineWidth = 4;
280	    ctx.shadowColor = '#f59e0b'; ctx.shadowBlur = 18; ctx.stroke();
281	  }
282	
283	  if (displayPermanentSec < permanentSec) {
284	    displayPermanentSec += Math.ceil((permanentSec - displayPermanentSec) * 0.2);
285	    poolValEl.textContent = formatDuration(displayPermanentSec);
286	  }
287	  ctx.restore();
288	  requestAnimationFrame(draw);
289	}
