9	function formatBalance(seconds: number): string {
10	  const total = Math.floor(seconds)
11	  const d = Math.floor(total / 86400)
12	  const h = Math.floor((total % 86400) / 3600)
13	  const m = Math.floor((total % 3600) / 60)
14	  const s = total % 60
15	  if (d > 0) return `${d}d ${h}h ${m}m`
16	  if (h > 0) return `${h}h ${m}m ${s}s`
17	  if (m > 0) return `${m}m ${s}s`
