21	// Ease-out expo number roll
22	function useAnimatedValue(target: number, duration = 1100): number {
23	  const [display, setDisplay] = useState(target)
24	  const raf = useRef<number | null>(null)
25	  const anim = useRef<{ from: number; to: number; t0: number } | null>(null)
26	
27	  useEffect(() => {
28	    const from = display
29	    if (from === target) return
30	    anim.current = { from, to: target, t0: performance.now() }
31	    function tick(now: number) {
32	      const { from, to, t0 } = anim.current!
33	      const p = Math.min((now - t0) / duration, 1)
34	      const ease = p === 1 ? 1 : 1 - Math.pow(2, -10 * p)
35	      setDisplay(from + (to - from) * ease)
36	      if (p < 1) raf.current = requestAnimationFrame(tick)
37	    }
38	    raf.current = requestAnimationFrame(tick)
39	    return () => { if (raf.current) cancelAnimationFrame(raf.current) }
40	  }, [target]) // eslint-disable-line react-hooks/exhaustive-deps
41	
42	  return display
43	}
