484	    p.style.setProperty('--dur',  `${dur}ms`)
485	    p.style.setProperty('--sz',   `${size}px`)
486	    field.appendChild(p)
487	    setTimeout(() => p.classList.add('active'), 400 + Math.random() * 500)
488	  }
489	}
