// path: src/apps/heraclitus/components/YellowPoolTab.tsx

import React, { useState, useEffect, useRef } from 'react'
import { fetchPoolState, depositToPool } from '../services/heraclitusApi'
import type { YellowTimePoolState } from '../types'

// ── Helpers ──────────────────────────────────────────────────────────────────

function formatBalance(seconds: number): string {
  const total = Math.floor(seconds)
  const d = Math.floor(total / 86400)
  const h = Math.floor((total % 86400) / 3600)
  const m = Math.floor((total % 3600) / 60)
  const s = total % 60
  if (d > 0) return `${d}d ${h}h ${m}m`
  if (h > 0) return `${h}h ${m}m ${s}s`
  if (m > 0) return `${m}m ${s}s`
  return `${s}s`
}

// Ease-out expo number roll
function useAnimatedValue(target: number, duration = 1100): number {
  const [display, setDisplay] = useState(target)
  const raf = useRef<number | null>(null)
  const anim = useRef<{ from: number; to: number; t0: number } | null>(null)

  useEffect(() => {
    const from = display
    if (from === target) return
    anim.current = { from, to: target, t0: performance.now() }
    function tick(now: number) {
      const { from, to, t0 } = anim.current!
      const p = Math.min((now - t0) / duration, 1)
      const ease = p === 1 ? 1 : 1 - Math.pow(2, -10 * p)
      setDisplay(from + (to - from) * ease)
      if (p < 1) raf.current = requestAnimationFrame(tick)
    }
    raf.current = requestAnimationFrame(tick)
    return () => { if (raf.current) cancelAnimationFrame(raf.current) }
  }, [target]) // eslint-disable-line react-hooks/exhaustive-deps

  return display
}

// ── CSS injected once — mirrors black-hole.html technique ─────────────────────

const POOL_CSS = `
.yp-scene {
  position: relative;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  overflow: hidden;
}

.yp-stars {
  position: absolute;
  inset: 0;
  opacity: .28;
  pointer-events: none;
  background-image:
    radial-gradient(circle, rgba(255,216,107,.85) 0 1px, transparent 1.4px),
    radial-gradient(circle, rgba(255,255,220,.5) 0 1px, transparent 1.4px);
  background-size: 97px 97px, 163px 163px;
  background-position: 11px 23px, 71px 61px;
}

/* ── ORB ── */
.yp-orb-wrap {
  position: relative;
  width: 340px;
  height: 340px;
  flex-shrink: 0;
}

.yp-core {
  position: absolute;
  inset: 28%;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    #1a0e00 0 52%,
    #2a1600 65%,
    rgba(60,36,0,.7) 78%,
    transparent 100%
  );
  box-shadow:
    0 0 22px #000,
    0 0 60px rgba(180,120,0,.35),
    0 0 130px rgba(140,90,0,.18);
}

.yp-ring {
  position: absolute;
  left: 50%; top: 50%;
  width: var(--d);
  height: var(--d);
  border-radius: 50%;
  border: var(--th) solid transparent;
  transform-origin: center center;
  transform: translate(-50%,-50%) rotateX(var(--tilt)) rotateZ(0deg);
  transform-style: preserve-3d;
  mix-blend-mode: screen;
  pointer-events: none;
  opacity: var(--op);
}

.yp-ring-1 { --d:350px; --th:4px; --tilt:69deg; --op:.92;
  border-top-color:   rgba(255,216,107,.95);
  border-right-color: rgba(200,140,0,.90);
  border-bottom-color:rgba(140,90,0,.55);
  filter: drop-shadow(0 0 9px rgba(255,200,60,.9));
  animation: ypR1 2000ms linear infinite;
}
.yp-ring-2 { --d:298px; --th:3px; --tilt:63deg; --op:.84;
  border-left-color:  rgba(255,245,180,.90);
  border-top-color:   rgba(255,200,80,.88);
  border-bottom-color:rgba(160,100,0,.52);
  filter: drop-shadow(0 0 13px rgba(255,220,100,.92));
  animation: ypR2 1350ms linear infinite reverse;
}
.yp-ring-3 { --d:248px; --th:5px; --tilt:57deg; --op:.78;
  border-right-color: rgba(255,255,200,.75);
  border-left-color:  rgba(200,130,0,.90);
  filter: blur(1px) drop-shadow(0 0 15px rgba(255,200,60,.88));
  animation: ypR3 840ms linear infinite;
}
.yp-ring-4 { --d:204px; --th:3px; --tilt:51deg; --op:.64;
  border-top-color:   rgba(255,240,160,.82);
  border-bottom-color:rgba(180,110,0,.86);
  filter: drop-shadow(0 0 11px rgba(255,210,80,.80));
  animation: ypR4 640ms linear infinite reverse;
}

@keyframes ypR1 {
  from { transform: translate(-50%,-50%) rotateX(69deg) rotateZ(0deg); }
  to   { transform: translate(-50%,-50%) rotateX(69deg) rotateZ(360deg); }
}
@keyframes ypR2 {
  from { transform: translate(-50%,-50%) rotateX(63deg) rotateZ(360deg); }
  to   { transform: translate(-50%,-50%) rotateX(63deg) rotateZ(0deg); }
}
@keyframes ypR3 {
  from { transform: translate(-50%,-50%) rotateX(57deg) rotateZ(0deg); }
  to   { transform: translate(-50%,-50%) rotateX(57deg) rotateZ(360deg); }
}
