    }
  }

  return (
    <div className="space-y-6">
      {/* ── 1. Monolithic Command Bar (min-h-[64px]) ────────────────────────── */}
      <div className="p-4 rounded-2xl bg-[#0f0b17]/95 border border-[#2d223c] shadow-2xl">
        <div className="flex flex-col lg:flex-row items-stretch lg:items-center gap-3">
          {/* Main URL Input */}
          <div className="relative flex-1">
            <input
              type="text"
              value={url}
              onChange={(e) => setUrl(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleCalculate()}
              placeholder="Paste YouTube Playlist link (e.g., https://youtube.com/playlist?list=...)"
              className="w-full min-h-[52px] px-4 rounded-xl bg-[#171222] border border-[#372a4c] focus:border-[#ffd86b] text-sm font-mono text-white placeholder-[#685b7b] outline-none transition shadow-inner"
            />
          </div>

          {/* Action Buttons Row */}
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={handlePaste}
              className="min-h-[52px] px-4 rounded-xl bg-[#1c1528] hover:bg-[#281d39] border border-[#3e2e54] text-xs font-cinzel font-bold text-[#c4b5d6] hover:text-white transition flex items-center gap-1.5 cursor-pointer active:scale-95"
              title="Paste from clipboard"
            >
              <Clipboard className="w-4 h-4" />
              <span className="hidden sm:inline">Paste</span>
            </button>

            <button
              type="button"
              onClick={handlePreset}
              className="min-h-[52px] px-4 rounded-xl bg-[#1c1528] hover:bg-[#281d39] border border-[#3e2e54] text-xs font-cinzel font-bold text-[#ffd86b] hover:border-[#ffd86b] transition flex items-center gap-1.5 cursor-pointer active:scale-95"
              title="Load sample Fusion 360 playlist"
            >
              <Sparkles className="w-4 h-4" />
              <span className="hidden sm:inline">Sample</span>
            </button>

            {url && (
              <button
                type="button"
                onClick={() => {
                  setUrl('')
                  setError(null)
                }}
                className="min-h-[52px] px-3 rounded-xl bg-[#1c1528] hover:bg-[#281d39] border border-[#3e2e54] text-[#8c7a9e] hover:text-rose-400 transition cursor-pointer"
                title="Clear input"
              >
                <RotateCcw className="w-4 h-4" />
              </button>
            )}

            {/* Calculate Button */}
            <button
              type="button"
              onClick={() => handleCalculate()}
              disabled={isLoading}
              className="min-h-[52px] px-6 rounded-xl bg-gradient-to-r from-[#d4af37] via-[#ffd86b] to-[#b38f22] text-black font-cinzel font-extrabold text-xs tracking-wider transition-all duration-150 shadow-gold-md hover:brightness-110 active:scale-95 cursor-pointer disabled:opacity-50 flex items-center gap-2"
            >
              <Play className={`w-4 h-4 fill-black ${isLoading ? 'animate-spin' : ''}`} />
              <span>{isLoading ? 'CALCULATING...' : 'CALCULATE DURATION'}</span>
            </button>
          </div>
        </div>
      </div>

      {/* ── 2. Error Display Banner ────────────────────────────────────────── */}
      {error && (
        <div className="p-4 rounded-xl bg-red-950/70 border border-red-700/60 flex items-center gap-3 text-red-200 text-xs font-mono shadow-lg">
          <AlertCircle className="w-5 h-5 text-red-400 flex-shrink-0" />
          <div className="flex-1">{error}</div>
        </div>
      )}

      {/* ── 3. Results Dashboard ───────────────────────────────────────────── */}
      {result && (
        <div className="space-y-6">
          {/* Header Info + Deposit Action */}
          <div className="p-4 rounded-xl bg-[#140f1e]/80 border border-[#2b213a] flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
            <div className="flex-1">
              <h2 className="font-cinzel font-bold text-lg text-white">
                {result.title}
              </h2>
              <p className="text-xs font-mono text-[#8c7a9e]">
                Uploader / Channel: <span className="text-[#ffd86b] font-bold">{result.uploader}</span>
              </p>
            </div>
            <div className="flex flex-col sm:flex-col gap-2 sm:gap-2">
              <div className="text-right">
                <span className="font-cinzel text-xs text-[#8c7a9e] uppercase tracking-wider">
                  Status
                </span>
                <div className="text-xs font-mono font-bold text-emerald-400">
                  100% Calculated via yt-dlp
                </div>
              </div>
              {depositSuccess ? (
                <div className="flex items-center gap-2 px-3 py-1.5 rounded-lg bg-emerald-900/40 border border-emerald-500/60 text-emerald-400 text-xs font-mono">
                  <CheckCircle className="w-4 h-4" />
                  <span>Deposited!</span>
                </div>
              ) : (
                <button
                  onClick={handleDepositToPool}
                  disabled={isDepositing}
                  className="flex items-center gap-2 px-3 py-1.5 rounded-lg bg-[#ffd86b]/20 hover:bg-[#ffd86b]/30 disabled:bg-[#4a3f5c] border border-[#ffd86b]/60 text-[#ffd86b] disabled:text-[#8c7a9e] text-xs font-mono font-bold transition-colors cursor-pointer"
                >
                  <Droplet className="w-3.5 h-3.5" />
                  <span>{isDepositing ? 'Depositing...' : 'Add to Pool'}</span>
                </button>
              )}
            </div>
          </div>

          {/* Metric Telemetry Cards */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {/* Total Runtime */}
            <div className="p-4 rounded-2xl bg-[#140f1e] border border-[#332545] shadow-lg flex items-center gap-3.5">
              <div className="w-11 h-11 rounded-xl bg-gradient-to-br from-[#ffd86b]/20 to-[#f97316]/20 border border-[#ffd86b]/40 flex items-center justify-center flex-shrink-0">
                <Clock className="w-6 h-6 text-[#ffd86b]" />
              </div>
              <div>
                <span className="text-[10px] font-cinzel font-bold text-[#8c7a9e] uppercase tracking-wider">
                  Total Duration (1.0x)
                </span>
                <div className="font-mono text-xl font-black text-white mt-0.5">
                  {result.formatted_duration}
                </div>
              </div>
            </div>

            {/* Total Videos */}
            <div className="p-4 rounded-2xl bg-[#140f1e] border border-[#332545] shadow-lg flex items-center gap-3.5">
              <div className="w-11 h-11 rounded-xl bg-gradient-to-br from-sky-500/20 to-blue-600/20 border border-sky-400/40 flex items-center justify-center flex-shrink-0">
                <Layers className="w-6 h-6 text-sky-400" />
              </div>
              <div>
                <span className="text-[10px] font-cinzel font-bold text-[#8c7a9e] uppercase tracking-wider">
                  Total Videos
                </span>
                <div className="font-mono text-xl font-black text-white mt-0.5">
                  {result.total_videos}{' '}
                  <span className="text-xs font-normal text-emerald-400">
                    ({result.active_videos} active)
                  </span>
                </div>
              </div>
            </div>

            {/* Average Video Length */}
            <div className="p-4 rounded-2xl bg-[#140f1e] border border-[#332545] shadow-lg flex items-center gap-3.5">
              <div className="w-11 h-11 rounded-xl bg-gradient-to-br from-purple-500/20 to-pink-600/20 border border-purple-400/40 flex items-center justify-center flex-shrink-0">
                <Activity className="w-6 h-6 text-purple-400" />
              </div>
              <div>
                <span className="text-[10px] font-cinzel font-bold text-[#8c7a9e] uppercase tracking-wider">
                  Average Length
                </span>
                <div className="font-mono text-xl font-black text-white mt-0.5">
                  {result.average_duration_formatted}
                </div>
              </div>
            </div>

            {/* Raw Seconds */}
            <div className="p-4 rounded-2xl bg-[#140f1e] border border-[#332545] shadow-lg flex items-center gap-3.5">
              <div className="w-11 h-11 rounded-xl bg-gradient-to-br from-amber-500/20 to-emerald-600/20 border border-amber-400/40 flex items-center justify-center flex-shrink-0">
                <Hash className="w-6 h-6 text-amber-400" />
              </div>
              <div>
                <span className="text-[10px] font-cinzel font-bold text-[#8c7a9e] uppercase tracking-wider">
                  Raw Seconds
                </span>
                <div className="font-mono text-xl font-black text-white mt-0.5">
                  {Math.round(result.total_seconds).toLocaleString()}s
                </div>
              </div>
            </div>
          </div>

          {/* ── 4. Speed Multipliers Deck ──────────────────────────────────── */}
          <div className="space-y-2">
            <h3 className="font-cinzel font-bold text-xs text-[#8c7a9e] uppercase tracking-wider">
              Playback Velocity Matrix
            </h3>
            <SpeedBreakdownCards
              breakdowns={result.speed_breakdowns}
              selectedSpeed={selectedSpeed}
              onSelectSpeed={setSelectedSpeed}
            />
          </div>

          {/* ── 5. Video Manifest Outliner ─────────────────────────────────── */}
          <VideoListTable
            videos={result.videos}
            playlistTitle={result.title}
          />
        </div>
      )}
    </div>
  )
}

// path: src/apps/heraclitus/components/SpeedBreakdownCards.tsx

import React from 'react'
import { FastForward, Clock, Zap } from 'lucide-react'
import type { SpeedBreakdown } from '../types'

interface SpeedBreakdownCardsProps {
  breakdowns: SpeedBreakdown[]
  selectedSpeed: number
  onSelectSpeed: (speed: number) => void
}

export const SpeedBreakdownCards: React.FC<SpeedBreakdownCardsProps> = ({
  breakdowns,
  selectedSpeed,
  onSelectSpeed,
}) => {
  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-3.5">
      {breakdowns.map((item) => {
        const isSelected = selectedSpeed === item.speed
        const isNormal = item.speed === 1.0

        return (
          <button
            key={item.speed}
            type="button"
            onClick={() => onSelectSpeed(item.speed)}
            className={`min-h-[96px] w-full p-4 rounded-2xl border text-left transition-all duration-150 cursor-pointer flex flex-col justify-between select-none relative overflow-hidden group ${
              isSelected
                ? 'bg-gradient-to-br from-[#261d33] via-[#1a1424] to-[#120f1a] border-[#ffd86b] shadow-[0_0_20px_rgba(255,216,107,0.22)]'
                : 'bg-[#110d18]/90 hover:bg-[#191322] border-[#2b2138] hover:border-[#4d3a66] text-[#9c93a8]'
            }`}
          >
            {/* Top row: Speed label & icon */}
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-1.5">
                {isNormal ? (
                  <Clock className={`w-4 h-4 ${isSelected ? 'text-[#ffd86b]' : 'text-[#7d7190]'}`} />
                ) : (
                  <FastForward className={`w-4 h-4 ${isSelected ? 'text-[#ffd86b]' : 'text-[#7d7190]'}`} />
                )}
                <span className={`font-mono text-sm font-black ${isSelected ? 'text-white' : 'text-[#cbd5e1]'}`}>
                  {item.speed.toFixed(2)}x
                </span>
              </div>
              {item.speed > 1.0 && (
                <div className="flex items-center gap-1 px-1.5 py-0.5 rounded bg-amber-500/10 border border-amber-500/20 text-[10px] font-mono text-amber-300">
                  <Zap className="w-2.5 h-2.5" />
                  <span>-{item.time_saved_formatted}</span>
                </div>
              )}
            </div>

            {/* Bottom row: Adjusted duration */}
            <div className="mt-2">
              <div className="text-[10px] uppercase font-cinzel tracking-wider text-[#7d7190]">
                {isNormal ? 'Standard Runtime' : `At ${item.speed.toFixed(2)}x Velocity`}
              </div>
              <div className={`font-mono text-base font-black tracking-tight mt-0.5 ${
                isSelected ? 'text-[#ffd86b]' : 'text-slate-200'
              }`}>
                {item.formatted}
              </div>
            </div>

            {/* Decorative active glow bar */}
            {isSelected && (
              <div className="absolute bottom-0 left-0 right-0 h-1 bg-gradient-to-r from-[#ffd86b] via-[#f59e0b] to-[#ffd86b]" />
            )}
          </button>
        )
      })}
    </div>
  )
}

// path: src/apps/heraclitus/components/VideoListTable.tsx

import React, { useState, useMemo } from 'react'
import { Search, ExternalLink, Film, Check, Copy } from 'lucide-react'
import type { VideoItem } from '../types'

interface VideoListTableProps {
  videos: VideoItem[]
  playlistTitle: string
}

export const VideoListTable: React.FC<VideoListTableProps> = ({ videos, playlistTitle }) => {
  const [searchTerm, setSearchTerm] = useState('')
  const [copied, setCopied] = useState(false)

  const filteredVideos = useMemo(() => {
    const q = searchTerm.toLowerCase().trim()
    if (!q) return videos
    return videos.filter((v) => v.title.toLowerCase().includes(q))
  }, [videos, searchTerm])

  const handleCopySummary = async () => {
    const lines = [
      `Playlist: ${playlistTitle}`,
      `Total Tracks: ${videos.length}`,
      ...videos.map((v, i) => `${i + 1}. [${v.duration_formatted}] ${v.title} - ${v.url}`),
    ]
    await navigator.clipboard.writeText(lines.join('\n'))
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  return (
    <div className="bg-[#100d16]/95 border border-[#2b2138] rounded-2xl p-5 shadow-xl">
      {/* Search & Actions Header */}
      <div className="flex flex-col sm:flex-row items-center justify-between gap-4 mb-4">
        <div className="flex items-center gap-3 w-full sm:w-auto">
          <Film className="w-5 h-5 text-[#ffd86b]" />
          <div>
            <h3 className="font-cinzel font-bold text-sm text-white uppercase tracking-wider">
              Playlist Track Manifest
            </h3>
            <span className="text-xs text-[#8c7a9e] font-mono">
              Showing {filteredVideos.length} of {videos.length} videos
            </span>
          </div>
        </div>

        <div className="flex items-center gap-3 w-full sm:w-auto">
          {/* Search Input (min-h-[44px] per Monolithic Vertical Height Law) */}
          <div className="relative flex-1 sm:w-64">
            <Search className="w-4 h-4 text-[#8c7a9e] absolute left-3 top-1/2 -translate-y-1/2" />
            <input
              type="text"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Filter tracks by title..."
              className="w-full min-h-[44px] pl-9 pr-3 rounded-xl bg-[#171220] border border-[#322642] focus:border-[#ffd86b] text-xs font-mono text-white placeholder-[#6a5e78] outline-none transition"
            />
          </div>

          {/* Copy Summary Button */}
          <button
            type="button"
            onClick={handleCopySummary}
            className="min-h-[44px] px-3.5 rounded-xl bg-[#1c1527] hover:bg-[#271d36] border border-[#44335a] hover:border-[#ffd86b] text-xs font-cinzel font-bold text-[#ffd86b] transition flex items-center gap-1.5 cursor-pointer whitespace-nowrap active:scale-95"
            title="Copy manifest to clipboard"
          >
            {copied ? <Check className="w-3.5 h-3.5 text-emerald-400" /> : <Copy className="w-3.5 h-3.5" />}
            <span>{copied ? 'Copied!' : 'Copy Manifest'}</span>
          </button>
        </div>
      </div>

      {/* Track List Outliner */}
      <div className="max-h-[420px] overflow-y-auto space-y-2 pr-1 custom-scrollbar">
        {filteredVideos.map((video, idx) => (
          <div
            key={video.id || idx}
            className="min-h-[52px] p-3 rounded-xl bg-[#140f1c] hover:bg-[#1b1526] border border-[#261d33] hover:border-[#3e2e54] flex items-center justify-between gap-3 transition-colors group"
          >
            <div className="flex items-center gap-3 min-w-0">
              <span className="w-7 text-right font-mono text-xs font-bold text-[#6a5e78] flex-shrink-0">
                {(idx + 1).toString().padStart(2, '0')}
              </span>
              <span className="font-sans text-xs text-slate-200 group-hover:text-white truncate font-medium">
                {video.title}
              </span>
            </div>

            <div className="flex items-center gap-3 flex-shrink-0">
              <span className={`font-mono text-xs font-bold px-2.5 py-1 rounded-lg border ${
                video.duration !== null
                  ? 'bg-[#1b1624] border-[#382b4a] text-[#ffd86b]'
                  : 'bg-red-950/40 border-red-800/40 text-red-400'
              }`}>
                {video.duration_formatted}
              </span>

              {video.url && (
                <a
                  href={video.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="p-1.5 rounded-lg bg-[#1e172a] hover:bg-[#2b1f3c] text-[#8c7a9e] hover:text-white transition"
                  title="Open video in new tab"
                >
                  <ExternalLink className="w-3.5 h-3.5" />
                </a>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

