34	  /* Spacing & Borders */
35	  --radius: 12px;
36	  --radius-sm: 8px;
37	  --radius-lg: 20px;
38	  --shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
39	  --shadow-lg: 0 8px 32px rgba(0, 0, 0, 0.4);
40	  --shadow-gold-sm: 0 0 10px rgba(212, 175, 55, 0.3);
41	  --shadow-gold-md: 0 0 18px rgba(212, 175, 55, 0.4);
