51	}
52	
53	* {
54	  margin: 0;
55	  padding: 0;
56	  box-sizing: border-box;
57	}
58	
59	body {
60	  font-family: 'Inter', system-ui, -apple-system, sans-serif;
61	  background: var(--bg-primary);
62	  color: var(--text-primary);
63	  min-height: 100dvh;
64	  -webkit-tap-highlight-color: transparent;
65	  -webkit-font-smoothing: antialiased;
66	  -moz-osx-font-smoothing: grayscale;
67	}
68	
69	/* Custom Scrollbar */
70	::-webkit-scrollbar {
71	  width: 10px;
72	  height: 10px;
73	}
74	::-webkit-scrollbar-track {
75	  background: var(--bg-primary);
76	}
77	::-webkit-scrollbar-thumb {
78	  background: var(--bg-card);
79	  border-radius: var(--radius-sm);
80	  border: 2px solid var(--bg-primary);
81	}
82	::-webkit-scrollbar-thumb:hover {
83	  background: var(--accent);
84	  box-shadow: 0 0 10px var(--glow);
85	}
86	
87	/* Smooth Hardware-Accelerated Micro-Transitions */
88	button, a, .interactive {
89	  transition: color 0.08s ease-out, background-color 0.08s ease-out, border-color 0.08s ease-out, transform 0.06s ease-out, opacity 0.08s ease-out, box-shadow 0.08s ease-out;
90	  user-select: none;
91	}
92	
93	button:active:not(:disabled), .interactive:active:not(:disabled) {
94	  transform: scale(0.98);
95	}
96	
97	/* Backdrop Gradient - Gate of Babylon Style */
98	.portal-backdrop {
99	  background: radial-gradient(circle at 50% -10%, rgba(212, 175, 55, 0.12) 0%, rgba(132, 24, 34, 0.08) 35%, #070609 80%);
100	}
101	
102	.gold-text-gradient {
103	  background: linear-gradient(135deg, #ffd86b 0%, #d4af37 50%, #aa8214 100%);
104	  -webkit-background-clip: text;
105	  -webkit-text-fill-color: transparent;
106	  background-clip: text;
107	}
108	
109	/* Card Hover Effects - Golden Border Glow */
110	.card-glow, .golden-border-glow {
111	  border: 1px solid var(--border);
112	  transition: border-color 0.1s ease-out, box-shadow 0.1s ease-out, transform 0.1s ease-out;
113	}
114	
115	.card-glow:hover, .golden-border-glow:hover {
116	  border-color: var(--accent);
117	  box-shadow: 0 0 18px var(--glow), inset 0 0 12px rgba(212, 175, 55, 0.08);
118	  transform: translateY(-2px);
119	}
120	
121	.shadow-gold-sm {
122	  box-shadow: var(--shadow-gold-sm);
123	}
124	
125	.shadow-gold-md {
126	  box-shadow: var(--shadow-gold-md);
127	}
128	
129	.shadow-portal {
130	  box-shadow: var(--shadow-portal);
131	}
132	
133	/* Glassmorphism Effect */
134	.glass {
135	  background: rgba(26, 26, 36, 0.6);
136	  backdrop-filter: blur(12px);
137	  -webkit-backdrop-filter: blur(12px);
138	  border: 1px solid rgba(255, 255, 255, 0.1);
139	}
140	
141	/* Shimmer Animation */
142	@keyframes shimmer {
143	  0% { background-position: -200% 0; }
144	  100% { background-position: 200% 0; }
145	}
146	
147	.shimmer {
148	  background: linear-gradient(
149	    90deg,
150	    transparent 0%,
151	    rgba(124, 109, 240, 0.1) 50%,
152	    transparent 100%
153	  );
154	  background-size: 200% 100%;
155	  animation: shimmer 3s infinite;
156	}
157	
158	/* Pulse Glow - Gold Edition */
159	@keyframes pulse-glow {
160	  0%, 100% {
161	    box-shadow: 0 0 10px var(--glow);
162	  }
163	  50% {
164	    box-shadow: 0 0 20px var(--glow), 0 0 30px var(--glow);
165	  }
166	}
167	
168	.pulse-glow {
169	  animation: pulse-glow 2s infinite ease-in-out;
170	}
171	
172	@keyframes pulse-slow {
173	  0%, 100% {
174	    opacity: 1;
175	  }
176	  50% {
177	    opacity: 0.6;
178	  }
179	}
180	
181	.animate-pulse-slow {
182	  animation: pulse-slow 3s infinite ease-in-out;
183	}
184	
185	/* Success Glow */
186	@keyframes success-pulse {
187	  0%, 100% {
188	    box-shadow: 0 0 10px var(--success-soft);
189	    border-color: var(--success);
190	  }
191	  50% {
192	    box-shadow: 0 0 20px rgba(52, 211, 153, 0.3);
193	    border-color: var(--success);
194	  }
195	}
196	
197	.success-glow {
198	  animation: success-pulse 2s infinite ease-in-out;
199	}
200	
201	/* ============================================================================= */
202	/* IDE TOP-RIGHT HUD CSS ANIMATIONS — GATE OF BABYLON CYBER-IMPERIAL TELEMETRY  */
203	/* ============================================================================= */
204	
205	@keyframes ide-hud-border-glow {
206	  0%, 100% {
207	    border-color: rgba(212, 175, 55, 0.45);
208	    box-shadow: 0 0 18px rgba(212, 175, 55, 0.25), inset 0 0 12px rgba(212, 175, 55, 0.08);
209	  }
210	  50% {
211	    border-color: rgba(255, 216, 107, 0.9);
