213	  }
214	}
215	
216	@keyframes ide-scanline-sweep {
217	  0% {
218	    transform: translateY(-100%);
219	    opacity: 0;
220	  }
221	  30% {
222	    opacity: 0.85;
223	  }
224	  70% {
225	    opacity: 0.85;
226	  }
227	  100% {
228	    transform: translateY(200%);
229	    opacity: 0;
230	  }
231	}
232	
233	@keyframes ide-chrono-spin {
234	  0% {
235	    transform: rotate(0deg);
236	  }
237	  100% {
238	    transform: rotate(360deg);
239	  }
240	}
241	
242	@keyframes ide-energy-pulse {
243	  0%, 100% {
244	    transform: scale(1);
245	    filter: drop-shadow(0 0 4px rgba(255, 216, 107, 0.6));
246	  }
