  }
  100% {
    transform: translate(var(--tp-burst-x, 0px), var(--tp-burst-y, 0px)) scale(0) rotate(360deg);
    opacity: 0;
  }
}

/* --- Theme-Specific Variations --- */

/* Chrono Spool (Thermal Blast) */
.tp-theme-chrono {
