.tp-theme-supernova {
  --tp-primary: #fb923c;
  --tp-secondary: #f97316;
  --tp-glow: rgba(251, 146, 60, 0.8);
  --tp-particle-a: #ffd700;
  --tp-particle-b: #ffffff;
  --tp-text: #fff7ed;
  --tp-text-glow: rgba(255, 247, 237, 0.9);
}

/* --- Utility Classes --- */

/* Container for animated elements */
.tp-animate {
  position: relative;
  overflow: visible;
  will-change: transform, opacity;
}

/* Animated element base */
.tp-animated-element {
  position: absolute;
  pointer-events: none;
  will-change: transform, opacity;
  backface-visibility: hidden;
