140	      osc.type = 'sine'; osc.frequency.setValueAtTime(freq, t); gain.gain.setValueAtTime(0.04, t);
141	      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.06); osc.start(t); osc.stop(t + 0.06);
142	    }
143	    osc.connect(gain); gain.connect(audioCtx.destination);
144	  } catch(e) {}
145	}
146	
147	function depositSession(seconds) {
148	  isSpooling = true; targetSpoolSec = seconds; spoolSec = 0; spoolProgress = 0;
149	  clearTimeout(lingerTimeout);
150	  burstBadgeEl.className = 'burst-badge spooling'; burstValEl.className = 'burst-val';
151	  burstLabelEl.textContent = 'ACCRETING MASS'; burstValEl.textContent = '0s';
152	}
153	
154	function triggerShatter() {
155	  isSpooling = false; playSound('shatter', 0);
156	  screenShake = Math.min(32, 10 + (targetSpoolSec / 3600) * 3);
157	  shockwaves.push({ r: 25, maxR: Math.min(W, H) * 0.7, alpha: 1.0 });
158	
159	  burstLabelEl.textContent = 'STELLAR YIELD';
160	  burstValEl.textContent = formatDuration(targetSpoolSec);
161	  burstValEl.className = 'burst-val lingering';
162	  burstBadgeEl.className = 'burst-badge slow-fade';
163	
164	  const pCount = Math.min(220, Math.max(45, Math.floor(targetSpoolSec / 80)));
165	  const secPerP = targetSpoolSec / pCount;
166	  for (let i = 0; i < pCount; i++) {
167	    const a = Math.random() * Math.PI * 2, sp = 5 + Math.random() * 18;
168	    particles.push({
169	      x: cx, y: cy, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 2,
170	      secVal: secPerP, age: 0, magnetWait: 14 + Math.random() * 16,
171	      size: 3 + Math.random() * 3.5, color: Math.random() > 0.4 ? '#f59e0b' : '#ef4444'
172	    });
173	  }
174	
175	  clearTimeout(lingerTimeout);
176	  lingerTimeout = setTimeout(() => { burstBadgeEl.className = 'burst-badge'; }, 1000);
177	}
178	
179	function resetAll() {
180	  clearTimeout(lingerTimeout); isSpooling = false; permanentSec = 0; displayPermanentSec = 0;
181	  particles = []; shockwaves = []; screenShake = 0; poolValEl.textContent = '0s';
182	  burstBadgeEl.className = 'burst-badge'; burstValEl.className = 'burst-val';
183	}
184	
185	function draw() {
186	  ctx.save();
187	  if (screenShake > 0) {
188	    ctx.translate((Math.random() - 0.5) * screenShake, (Math.random() - 0.5) * screenShake);
189	    screenShake *= 0.88; if (screenShake < 0.2) screenShake = 0;
190	  }
191	  ctx.fillStyle = 'rgba(2, 1, 6, 0.28)'; ctx.fillRect(-20, -20, W + 40, H + 40);
192	  const t = Date.now() * 0.002;
193	
194	  if (isSpooling) {
195	    spoolProgress += 0.045;
196	    spoolSec = Math.round(targetSpoolSec * Math.min(1.0, Math.pow(spoolProgress, 1.3)));
197	    burstValEl.textContent = formatDuration(spoolSec);
198	    screenShake = 1.0 + spoolProgress * 8;
199	    playSound('tick', 300 + spoolProgress * 700);
200	
201	    // Infalling accretion particles
202	    if (Math.random() < 0.6) {
203	      const a = Math.random() * Math.PI * 2, r = 140 + Math.random() * 50;
204	      stellarArcs.push({ a, r, speed: 6 + spoolProgress * 7 });
205	    }
206	    for (let i = stellarArcs.length - 1; i >= 0; i--) {
207	      const s = stellarArcs[i]; s.r -= s.speed;
208	      if (s.r <= 18) { stellarArcs.splice(i, 1); continue; }
209	      ctx.beginPath(); ctx.arc(cx + Math.cos(s.a) * s.r, cy + Math.sin(s.a) * s.r, 2, 0, Math.PI * 2);
210	      ctx.fillStyle = '#fde047'; ctx.fill();
211	    }
212	
213	    // Shrinking Hyper-Dense Core (Thermal Collapse)
214	    const coreR = Math.max(16, (44 - spoolProgress * 26)) + Math.sin(t * 18) * 3;
215	    ctx.beginPath(); ctx.arc(cx, cy, coreR, 0, Math.PI * 2);
216	    ctx.fillStyle = spoolProgress > 0.6 ? '#ffffff' : '#f97316';
217	    ctx.shadowColor = '#f59e0b'; ctx.shadowBlur = 30 + spoolProgress * 30; ctx.fill();
218	
219	    if (spoolProgress >= 1.0) triggerShatter();
220	  } else {
221	    // Resting Protostar
222	    ctx.beginPath(); ctx.arc(cx, cy, 34 + Math.sin(t * 3) * 2, 0, Math.PI * 2);
223	    ctx.fillStyle = '#f97316'; ctx.shadowColor = '#ea580c'; ctx.shadowBlur = 18; ctx.fill();
224	  }
225	
226	  // Shockwaves
227	  for (let i = shockwaves.length - 1; i >= 0; i--) {
228	    const sw = shockwaves[i]; sw.r += 14; sw.alpha -= 0.035;
229	    if (sw.alpha <= 0) { shockwaves.splice(i, 1); continue; }
230	    ctx.beginPath(); ctx.arc(cx, cy, sw.r, 0, Math.PI * 2);
231	    ctx.strokeStyle = `rgba(254, 240, 138, ${sw.alpha})`; ctx.lineWidth = 4;
232	    ctx.shadowColor = '#f59e0b'; ctx.shadowBlur = 20; ctx.stroke();
233	  }
234	
235	  // Particle Swarm to Vault
236	  for (let i = particles.length - 1; i >= 0; i--) {
237	    const p = particles[i]; p.age++;
238	    if (p.age < p.magnetWait) {
239	      p.x += p.vx; p.y += p.vy; p.vx *= 0.94; p.vy *= 0.94;
240	    } else {
241	      const dx = targetX - p.x, dy = targetY - p.y, dist = Math.hypot(dx, dy);
242	      if (dist < 26) {
243	        permanentSec += p.secVal; poolVaultEl.classList.add('absorb');
244	        setTimeout(() => poolVaultEl.classList.remove('absorb'), 70);
245	        playSound('absorb', 880 + (p.age % 10) * 80);
246	        particles.splice(i, 1); continue;
247	      }
248	      const pull = Math.min(26, 2.0 + (p.age - p.magnetWait) * 0.95);
249	      p.vx = (dx / dist) * pull; p.vy = (dy / dist) * pull; p.x += p.vx; p.y += p.vy;
250	    }
251	    ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
252	    ctx.fillStyle = p.color; ctx.shadowColor = p.color; ctx.shadowBlur = 10; ctx.fill();
253	  }
254	
255	  if (displayPermanentSec < permanentSec) {
256	    displayPermanentSec += Math.ceil((permanentSec - displayPermanentSec) * 0.2);
257	    poolValEl.textContent = formatDuration(displayPermanentSec);
258	  }
259	  ctx.restore();
260	  requestAnimationFrame(draw);
261	}
262	requestAnimationFrame(draw);
263	</script>
264	</body>
265	</html>

