1	@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700;800;900&family=Cinzel+Decorative:wght@400;700;900&display=swap');
2	@import "tailwindcss";
3	@import "./apps/heraclitus/animations/twoPhaseStyles.css";
4	@import "./apps/heraclitus/styles/heraclitusAnimations.css";
5	
6	/*
7	 * Universe 25 — Global Styles
8	 * Gate of Babylon inspired design system with imperial aesthetics
9	 */
10	
11	:root {
12	  /* Gate of Babylon Color Palette */
13	  --bg-primary: #070609;
14	  --bg-secondary: #0a080e;
15	  --bg-card: #120f18;
16	  --bg-elevated: #1a1424;
17	  --text-primary: #f5f0e8;
18	  --text-secondary: #9c93a8;
19	  --text-muted: #685c78;
20	  --accent: #d4af37;
21	  --accent-hover: #ffd86b;
22	  --accent-soft: rgba(212, 175, 55, 0.15);
23	  --accent-crimson: #841822;
24	  --border: #2b2238;
25	  --border-hover: #524124;
26	  --glow: rgba(212, 175, 55, 0.25);
27	
28	  /* Status Colors */
29	  --success: #34d399;
30	  --success-soft: rgba(52, 211, 153, 0.15);
31	  --warning: #fbbf24;
32	  --warning-soft: rgba(251, 191, 36, 0.15);
33	  --danger: #f87171;
34	  --danger-soft: rgba(248, 113, 113, 0.15);
35	
36	  /* Spacing & Borders */
37	  --radius: 12px;
38	  --radius-sm: 8px;
39	  --radius-lg: 20px;
40	  --shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
41	  --shadow-lg: 0 8px 32px rgba(0, 0, 0, 0.4);
42	  --shadow-gold-sm: 0 0 10px rgba(212, 175, 55, 0.3);
43	  --shadow-gold-md: 0 0 18px rgba(212, 175, 55, 0.4);
44	  --shadow-portal: 0 8px 40px rgba(212, 175, 55, 0.2);
45	}
46	
47	.font-cinzel {
48	  font-family: 'Cinzel', serif;
49	}
50	
51	.font-cinzel-dec {
52	  font-family: 'Cinzel Decorative', serif;
53	}
54	
55	* {
56	  margin: 0;
57	  padding: 0;
58	  box-sizing: border-box;
59	}
60	
61	body {
62	  font-family: 'Inter', system-ui, -apple-system, sans-serif;
63	  background: var(--bg-primary);
64	  color: var(--text-primary);
65	  min-height: 100dvh;
66	  -webkit-tap-highlight-color: transparent;
67	  -webkit-font-smoothing: antialiased;
68	  -moz-osx-font-smoothing: grayscale;
69	}
70	
71	/* Custom Scrollbar */
72	::-webkit-scrollbar {
73	  width: 10px;
74	  height: 10px;
75	}
76	::-webkit-scrollbar-track {
77	  background: var(--bg-primary);
78	}
79	::-webkit-scrollbar-thumb {
80	  background: var(--bg-card);
81	  border-radius: var(--radius-sm);
82	  border: 2px solid var(--bg-primary);
83	}
84	::-webkit-scrollbar-thumb:hover {
85	  background: var(--accent);
86	  box-shadow: 0 0 10px var(--glow);
87	}
88	
89	/* Smooth Hardware-Accelerated Micro-Transitions */
90	button, a, .interactive {
91	  transition: color 0.08s ease-out, background-color 0.08s ease-out, border-color 0.08s ease-out, transform 0.06s ease-out, opacity 0.08s ease-out, box-shadow 0.08s ease-out;
92	  user-select: none;
93	}
94	
95	button:active:not(:disabled), .interactive:active:not(:disabled) {
96	  transform: scale(0.98);
97	}
98	
99	/* Backdrop Gradient - Gate of Babylon Style */
100	.portal-backdrop {
101	  background: radial-gradient(circle at 50% -10%, rgba(212, 175, 55, 0.12) 0%, rgba(132, 24, 34, 0.08) 35%, #070609 80%);
102	}
103	
104	.gold-text-gradient {
105	  background: linear-gradient(135deg, #ffd86b 0%, #d4af37 50%, #aa8214 100%);
106	  -webkit-background-clip: text;
107	  -webkit-text-fill-color: transparent;
108	  background-clip: text;
109	}
110	
111	/* Card Hover Effects - Golden Border Glow */
112	.card-glow, .golden-border-glow {
113	  border: 1px solid var(--border);
114	  transition: border-color 0.1s ease-out, box-shadow 0.1s ease-out, transform 0.1s ease-out;
115	}
116	
117	.card-glow:hover, .golden-border-glow:hover {
118	  border-color: var(--accent);
119	  box-shadow: 0 0 18px var(--glow), inset 0 0 12px rgba(212, 175, 55, 0.08);
120	  transform: translateY(-2px);
121	}
122	
123	.shadow-gold-sm {
124	  box-shadow: var(--shadow-gold-sm);
125	}
126	
127	.shadow-gold-md {
128	  box-shadow: var(--shadow-gold-md);
129	}
130	
131	.shadow-portal {
132	  box-shadow: var(--shadow-portal);
133	}
134	
135	/* Glassmorphism Effect */
136	.glass {
137	  background: rgba(26, 26, 36, 0.6);
138	  backdrop-filter: blur(12px);
139	  -webkit-backdrop-filter: blur(12px);
140	  border: 1px solid rgba(255, 255, 255, 0.1);
141	}
142	
143	/* Shimmer Animation */
144	@keyframes shimmer {
145	  0% { background-position: -200% 0; }
146	  100% { background-position: 200% 0; }
147	}
148	
149	.shimmer {
150	  background: linear-gradient(
151	    90deg,
152	    transparent 0%,
153	    rgba(124, 109, 240, 0.1) 50%,
154	    transparent 100%
155	  );
156	  background-size: 200% 100%;
157	  animation: shimmer 3s infinite;
158	}
159	
160	/* Pulse Glow - Gold Edition */
161	@keyframes pulse-glow {
162	  0%, 100% {
163	    box-shadow: 0 0 10px var(--glow);
164	  }
165	  50% {
166	    box-shadow: 0 0 20px var(--glow), 0 0 30px var(--glow);
167	  }
168	}
169	
170	.pulse-glow {
171	  animation: pulse-glow 2s infinite ease-in-out;
172	}
173	
174	@keyframes pulse-slow {
175	  0%, 100% {
176	    opacity: 1;
177	  }
178	  50% {
179	    opacity: 0.6;
180	  }
181	}
182	
183	.animate-pulse-slow {
184	  animation: pulse-slow 3s infinite ease-in-out;
185	}
186	
187	/* Success Glow */
188	@keyframes success-pulse {
189	  0%, 100% {
190	    box-shadow: 0 0 10px var(--success-soft);
191	    border-color: var(--success);
192	  }
193	  50% {
194	    box-shadow: 0 0 20px rgba(52, 211, 153, 0.3);
195	    border-color: var(--success);
196	  }
197	}
198	
199	.success-glow {
200	  animation: success-pulse 2s infinite ease-in-out;
201	}
202	
203	/* ============================================================================= */
204	/* IDE TOP-RIGHT HUD CSS ANIMATIONS — GATE OF BABYLON CYBER-IMPERIAL TELEMETRY  */
205	/* ============================================================================= */
206	
207	@keyframes ide-hud-border-glow {
208	  0%, 100% {
209	    border-color: rgba(212, 175, 55, 0.45);
210	    box-shadow: 0 0 18px rgba(212, 175, 55, 0.25), inset 0 0 12px rgba(212, 175, 55, 0.08);
211	  }
212	  50% {
213	    border-color: rgba(255, 216, 107, 0.9);
214	    box-shadow: 0 0 28px rgba(212, 175, 55, 0.45), 0 0 50px rgba(132, 24, 34, 0.25), inset 0 0 20px rgba(255, 216, 107, 0.15);
215	  }
216	}
217	
218	@keyframes ide-scanline-sweep {
219	  0% {
220	    transform: translateY(-100%);
221	    opacity: 0;
222	  }
223	  30% {
224	    opacity: 0.85;
225	  }
226	  70% {
227	    opacity: 0.85;
228	  }
229	  100% {
230	    transform: translateY(200%);
231	    opacity: 0;
232	  }
233	}
234	
235	@keyframes ide-chrono-spin {
236	  0% {
237	    transform: rotate(0deg);
238	  }
239	  100% {
240	    transform: rotate(360deg);
241	  }
242	}
243	
244	@keyframes ide-energy-pulse {
245	  0%, 100% {
246	    transform: scale(1);
247	    filter: drop-shadow(0 0 4px rgba(255, 216, 107, 0.6));
248	  }
249	  50% {
250	    transform: scale(1.08);
251	    filter: drop-shadow(0 0 12px rgba(255, 216, 107, 1)) drop-shadow(0 0 20px rgba(245, 158, 11, 0.8));
252	  }
253	}
254	
255	@keyframes ide-number-flicker {
256	  0%, 100% {
257	    text-shadow: 0 0 10px rgba(255, 216, 107, 0.7), 0 0 20px rgba(212, 175, 55, 0.4);
258	  }
259	  50% {
260	    text-shadow: 0 0 16px rgba(255, 255, 255, 0.95), 0 0 30px rgba(255, 216, 107, 0.8);
261	  }
262	}
263	
264	.ide-hud-widget {
265	  position: relative;
266	  background: linear-gradient(135deg, rgba(22, 17, 30, 0.95) 0%, rgba(10, 8, 14, 0.98) 50%, rgba(26, 15, 28, 0.95) 100%);
267	  border: 1.5px solid rgba(212, 175, 55, 0.5);
