269	  animation: ide-hud-border-glow 3.5s infinite ease-in-out;
270	  backdrop-filter: blur(16px);
271	  -webkit-backdrop-filter: blur(16px);
272	  overflow: hidden;
273	  user-select: none;
274	}
275	
276	.ide-hud-widget::before {
277	  content: '';
278	  position: absolute;
279	  top: 0;
280	  left: 0;
281	  right: 0;
282	  height: 2px;
283	  background: linear-gradient(90deg, transparent 0%, rgba(255, 216, 107, 0.9) 50%, transparent 100%);
284	  animation: shimmer 2.5s infinite linear;
285	}
286	
287	.ide-scanline {
288	  position: absolute;
289	  inset: 0;
290	  pointer-events: none;
291	  background: linear-gradient(180deg, transparent 0%, rgba(212, 175, 55, 0.08) 50%, transparent 100%);
292	  height: 35%;
