294	}
295	
296	.ide-chrono-icon {
297	  animation: ide-energy-pulse 2.2s infinite ease-in-out;
298	}
299	
300	.ide-chrono-ring {
301	  animation: ide-chrono-spin 14s infinite linear;
302	}
303	
304	.ide-hazard-glow {
305	  animation: ide-number-flicker 3s infinite ease-in-out;
306	}
307	
308	/* Floating Animation */
309	@keyframes float {
310	  0%, 100% { transform: translateY(0px); }
311	  50% { transform: translateY(-10px); }
312	}
313	
314	.float {
315	  animation: float 3s infinite ease-in-out;
