35	      const p = Math.min((now - t0) / duration, 1)
36	      const ease = p === 1 ? 1 : 1 - Math.pow(2, -10 * p)
37	      setDisplay(from + (to - from) * ease)
38	      if (p < 1) raf.current = requestAnimationFrame(tick)
39	    }
40	    raf.current = requestAnimationFrame(tick)
41	    return () => { if (raf.current) cancelAnimationFrame(raf.current) }
42	  }, [target]) // eslint-disable-line react-hooks/exhaustive-deps
43	
44	  return display
45	}
