427	
428	function restart(el: HTMLElement | null, cls: string) {
429	  if (!el) return
430	  el.classList.remove(cls)
431	  void el.offsetWidth
432	  el.classList.add(cls)
433	}
434	
435	function spawnParticles(field: HTMLElement, count = 160) {
436	  field.innerHTML = ''
437	  for (let i = 0; i < count; i++) {
438	    const p = document.createElement('div')
439	    const radius = 140 + Math.random() * 360
440	    const angle  = Math.random() * 360
441	    const size   = 1.5 + Math.random() * 5
442	    const op     = .35 + Math.random() * .65
443	    const ot     = 900 + Math.random() * 1400
444	    const ct     = 700 + Math.random() * 600
445	    p.className = 'yp-particle'
446	    p.style.setProperty('--rad', `${radius}px`)
447	    p.style.setProperty('--ang', `${angle}deg`)
448	    p.style.setProperty('--sz',  `${size}px`)
449	    p.style.setProperty('--op',  String(op))
450	    p.style.setProperty('--ot',  `${ot}ms`)
451	    p.style.setProperty('--ct',  `${ct}ms`)
452	    field.appendChild(p)
453	  }
454	  requestAnimationFrame(() => {
455	    Array.from(field.children).forEach((child, i) => {
456	      setTimeout(() => child.classList.add('orbit'), Math.random() * 600 + i * 2)
457	    })
458	  })
459	}
460	
461	function compressParticles(field: HTMLElement) {
462	  Array.from(field.children).forEach((child, i) => {
463	    const el = child as HTMLElement
464	    const rad = el.style.getPropertyValue('--rad')
465	    const ang = parseFloat(el.style.getPropertyValue('--ang'))
466	    el.style.setProperty('--rad2', rad)
467	    el.style.setProperty('--ang2', `${ang + Math.random() * 90}deg`)
468	    setTimeout(() => {
469	      el.classList.remove('orbit')
470	      el.classList.add('compress')
471	    }, Math.random() * 400 + i * .7)
472	  })
473	}
474	
475	function spawnMatter(field: HTMLElement, count = 130) {
476	  field.innerHTML = ''
477	  for (let i = 0; i < count; i++) {
478	    const p = document.createElement('div')
479	    const angle    = Math.random() * 360
480	    const distance = 200 + Math.random() * 440
481	    const dur      = 800 + Math.random() * 900
482	    const size     = 1.5 + Math.random() * 5.5
483	    p.className = 'yp-matter'
484	    p.style.setProperty('--ang',  `${angle}deg`)
485	    p.style.setProperty('--dist', `${distance}px`)
486	    p.style.setProperty('--dur',  `${dur}ms`)
487	    p.style.setProperty('--sz',   `${size}px`)
488	    field.appendChild(p)
489	    setTimeout(() => p.classList.add('active'), 400 + Math.random() * 500)
490	  }
491	}
