function playSound(type, freq) {
  try {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === 'suspended') audioCtx.resume();
    const t = audioCtx.currentTime, osc = audioCtx.createOscillator(), gain = audioCtx.createGain();
    if (type === 'tick') {
      osc.type = 'triangle'; osc.frequency.setValueAtTime(freq, t); gain.gain.setValueAtTime(0.04, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.03); osc.start(t); osc.stop(t + 0.03);
    } else if (type === 'shatter') {
      osc.type = 'sawtooth'; osc.frequency.setValueAtTime(170, t); osc.frequency.exponentialRampToValueAtTime(30, t + 0.45);
      gain.gain.setValueAtTime(0.45, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.45); osc.start(t); osc.stop(t + 0.45);
    } else {
      osc.type = 'sine'; osc.frequency.setValueAtTime(freq, t); gain.gain.setValueAtTime(0.04, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.06); osc.start(t); osc.stop(t + 0.06);
    }
    osc.connect(gain); gain.connect(audioCtx.destination);
  } catch(e) {}
}

// ── Trigger Deposit: Spools 0s ➔ Target, then Explodes Instantly at Peak ──
function depositSession(seconds) {
  isSpooling = true; targetSpoolSec = seconds; spoolSec = 0; spoolProgress = 0;
  clearTimeout(lingerTimeout);
  burstBadgeEl.className = 'burst-badge spooling'; burstValEl.className = 'burst-val';
  burstLabelEl.textContent = 'ACCUMULATING'; burstValEl.textContent = '0s';
}

