    iframeRef.current.contentWindow.postMessage(
      { type: 'TRIGGER_DEPOSIT', seconds: rollResult.seconds },
      '*'
    )
  }

  // 2. Commit atomically to SQLite Single Source of Truth
  try {
    const updatedState = await depositToPool({
      seconds: rollResult.seconds,
      source: `Chrono Roll [${rollResult.tier}]`,
      category: 'gacha',
      speed: 1.0,
      notes: `${rollResult.label} • ${activeEngine.name}`,
    })
    setPoolState(updatedState)
    setBalanceSec(updatedState.balance_seconds)
    balanceSecRef.current = updatedState.balance_seconds
    setBackendOnline(true)
    setStatusNotice(`[${rollResult.tier}] +${rollResult.formatted} committed to SQLite SSOT ledger`)
    setTimeout(() => setStatusNotice(null), 3500)
  } catch {
    setBackendOnline(false)
    setBalanceSec((prev) => prev + rollResult.seconds)
    balanceSecRef.current += rollResult.seconds
    setStatusNotice(`[${rollResult.tier}] +${rollResult.formatted} recorded in active session`)
    setTimeout(() => setStatusNotice(null), 3500)
  } finally {
    setIsDepositing(false)
  }
}

