        <span id="btnText">Summon Chrono Duration (Gacha)</span>
      </span>
    </button>

    <div class="chrono-wager-bar">
      <span class="chrono-wager-label">ROLL WAGER:</span>
      <div class="chrono-wager-select-wrapper">
        <select id="wagerSelect" class="chrono-wager-select" onchange="handleWagerChange(this.value)">
