/* ── Integrated Controls (Golden Standard matching Image #3) ── */
.controls {
  pointer-events: auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  width: 100%;
  max-width: 460px;
  margin-bottom: 8px;
}

.variant-pill-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 4px 12px;
  border-radius: 999px;
  background: rgba(14, 10, 24, 0.65);
  border: 1px solid rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(8px);
}

.variant-pill {
  text-decoration: none;
  font-size: 11.5px;
  font-weight: 700;
  font-family: monospace;
  color: #8a7c9d;
  padding: 4px 10px;
  border-radius: 999px;
  transition: all 0.12s ease;
  display: flex;
  align-items: center;
  gap: 4px;
}

.variant-pill:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.08);
}

.variant-pill.active {
  color: #c084fc;
  background: rgba(192, 132, 252, 0.15);
  box-shadow: 0 0 10px rgba(192, 132, 252, 0.3);
  border: 1px solid rgba(192, 132, 252, 0.4);
}

/* PRIMARY SUMMON BUTTON (Image #3) */
.chrono-summon-button {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 56px;
  border: 1px solid rgba(168, 85, 247, 0.6);
  border-radius: 14px;
  padding: 12px 32px;
  font-size: 16px;
  font-weight: 800;
  color: #ffffff;
  background: linear-gradient(180deg, #371e68 0%, #5227a3 50%, #6830cc 100%);
  box-shadow: 0 8px 24px rgba(76, 29, 149, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.25);
  transition: transform 0.08s ease-out, box-shadow 0.08s ease-out, border-color 0.08s ease-out;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
}

.chrono-summon-button:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 12px 28px rgba(124, 58, 237, 0.6), 0 0 16px rgba(168, 85, 247, 0.4);
  border-color: #c084fc;
}

.chrono-summon-button:active:not(:disabled) {
  transform: translateY(0) scale(0.98);
}

.chrono-summon-button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.chrono-summon-button.is-spooling {
  background: linear-gradient(180deg, #2e1045 0%, #501777 50%, #7c2299 100%);
  border-color: #f0abfc;
  box-shadow: 0 8px 28px rgba(217, 70, 239, 0.45), 0 0 20px rgba(240, 171, 252, 0.5);
}

.btn-content {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.star-icon {
  font-size: 16px;
  filter: drop-shadow(0 0 6px #ffd86b);
}

/* WAGER BAR (Image #3) */
.chrono-wager-bar {
  width: 100%;
  padding: 8px 14px;
  border-radius: 12px;
  background: rgba(14, 10, 24, 0.95);
  border: 1px solid rgba(251, 191, 36, 0.35);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  user-select: none;
}

.chrono-wager-label {
  font-size: 11.5px;
  font-weight: 800;
  color: #ffd86b;
  font-family: monospace;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  white-space: nowrap;
}

.chrono-wager-select-wrapper {
  position: relative;
  flex: 1;
  display: flex;
  align-items: center;
}

.chrono-wager-select {
  width: 100%;
  appearance: none;
  -webkit-appearance: none;
  padding: 6px 28px 6px 12px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 800;
  font-family: monospace;
  border: 1px solid rgba(251, 191, 36, 0.35);
  background: rgba(18, 12, 30, 0.95);
  color: #f5f0e8;
  cursor: pointer;
  outline: none;
  transition: all 0.12s ease-out;
}

.chrono-wager-select:hover {
  border-color: #ffd700;
  box-shadow: 0 0 10px rgba(255, 215, 0, 0.25);
}

.select-arrow {
  position: absolute;
  right: 10px;
  font-size: 9px;
  color: #ffd86b;
  pointer-events: none;
}

.ticket-pill {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 8px;
